// Frischt Microsoft-Zugaenge auf, bevor sie ablaufen. Ohne diesen Lauf merkt
// niemand etwas, solange jemand aktiv fragt (der Skill erneuert dann selbst),
// aber Erinnerungen und naechtliche Zusammenfassungen laufen ins Leere.
// Zusaetzlich haelt er die 90-Tage-Frist offen: ein Zugang, der drei Monate
// nicht benutzt wird, verfaellt bei Microsoft endgueltig.

const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const pg = { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY, 'Content-Type': 'application/json' };

const credRows = await helpers.httpRequest({
  method: 'GET',
  url: SUPABASE_URL + '/rest/v1/template_credentials?template_id=eq.microsoft&select=cred_key,cred_value',
  headers: pg, json: true
});
const cred = {};
for (const c of (credRows || [])) cred[c.cred_key] = c.cred_value;
if (!cred.token_key || !cred.client_id) return [{ json: { result: 'Microsoft ist nicht eingerichtet, nichts zu tun.' } }];

// Faellig: laeuft in den naechsten 25 Minuten ab, ODER wurde seit 50 Tagen nicht
// erneuert (dann ist die 90-Tage-Frist in Sicht).
const faellig = await helpers.httpRequest({
  method: 'GET',
  url: SUPABASE_URL + "/rest/v1/user_oauth_tokens?provider=eq.microsoft&status=eq.connected" +
       "&or=(expires_at.lt." + new Date(Date.now() + 25 * 60000).toISOString() +
       ",last_refresh_at.lt." + new Date(Date.now() - 50 * 864e5).toISOString() + ")" +
       "&select=user_key,account_id,scopes",
  headers: pg, json: true
});

if (!faellig || !faellig.length) return [{ json: { result: 'Keine Zugaenge faellig.' } }];

// Runde 10 (19.10.2026): abgemeldet wird nur noch, wenn Microsoft den Zugang
// der Person selbst ablehnt (invalid_grant: abgelaufen, widerrufen, Passwort
// geaendert; interaction_required: neue Anmeldung oder MFA). Bis dahin fuehrte
// JEDER Fehler zu reconnect_required, auch ein Netzaussetzer oder ein Fehler
// beim Speichern: Sonja stand seit 08.10.2026 20:00 UTC mit "unbekannt" auf neu
// verbinden. Der Microsoft-Code war nie lesbar, weil der Task Runner
// e.response.body nicht durchreicht; deshalb wird die Antwort jetzt ohne
// Ausnahme gelesen (ignoreHttpStatusErrors). Alles andere gilt als
// voruebergehend: der Status bleibt connected, der Grund steht in status_detail,
// der naechste Lauf versucht es erneut (der Zugang bleibt faellig, solange er
// abgelaufen ist). invalid_client und unauthorized_client betreffen die App,
// nicht die Person: neu verbinden hilft dann niemandem.
const ok = [], kaputt = [], spaeter = [];
const PERSOENLICH = ['invalid_grant', 'interaction_required'];

async function vermerken(userKey, status, detail) {
  try {
    await helpers.httpRequest({ method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/mark_user_token', headers: pg,
      body: JSON.stringify({ p_user_key: userKey, p_provider: 'microsoft', p_status: status, p_detail: String(detail || '').slice(0, 200) }) });
  } catch (e) { /* Vermerk ist Nebensache, der naechste Lauf sieht den Zugang wieder */ }
}

for (const row of faellig) {
  let tokRow;
  try {
    const rows = await helpers.httpRequest({
      method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/get_user_token', headers: pg, json: true,
      body: JSON.stringify({ p_user_key: row.user_key, p_provider: 'microsoft', p_key: cred.token_key, p_account_id: row.account_id || '' })
    });
    tokRow = rows && rows[0];
  } catch (e) { spaeter.push(row.user_key + ' (nicht lesbar)'); continue; }
  if (!tokRow || !tokRow.refresh_token) {
    await vermerken(row.user_key, 'reconnect_required', 'kein refresh_token');
    kaputt.push(row.user_key + ' (kein refresh_token)');
    continue;
  }
  let res;
  try {
    res = await helpers.httpRequest({
      method: 'POST',
      url: 'https://login.microsoftonline.com/' + encodeURIComponent(cred.tenant_id) + '/oauth2/v2.0/token',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, json: true,
      returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 30000,
      body: 'client_id=' + encodeURIComponent(cred.client_id) +
            '&client_secret=' + encodeURIComponent(cred.client_secret) +
            '&refresh_token=' + encodeURIComponent(tokRow.refresh_token) +
            '&grant_type=refresh_token&scope=' + encodeURIComponent(row.scopes || tokRow.scopes || 'openid profile offline_access')
    });
  } catch (e) {
    const grund = 'Netz: ' + String((e && e.message) || e).slice(0, 120);
    await vermerken(row.user_key, 'connected', 'Erneuerung voruebergehend gescheitert (' + grund + ')');
    spaeter.push(row.user_key + ' (' + grund + ')');
    continue;
  }
  const status = Number(res && res.statusCode) || 0;
  let tok = res ? res.body : null;
  if (typeof tok === 'string') { try { tok = JSON.parse(tok); } catch (e) { tok = {}; } }
  tok = tok || {};
  if (status >= 200 && status < 300 && tok.access_token) {
    try {
      await helpers.httpRequest({
        method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/upsert_user_token', headers: pg,
        body: JSON.stringify({
          p_user_key: row.user_key, p_provider: 'microsoft', p_key: cred.token_key,
          p_access_token: tok.access_token, p_refresh_token: tok.refresh_token || '',
          p_expires_at: new Date(Date.now() + ((tok.expires_in || 3600) * 1000)).toISOString(),
          p_scopes: tok.scope || row.scopes || null, p_account_id: row.account_id || ''
        })
      });
      ok.push(row.user_key);
    } catch (e) {
      // Microsoft hat erneuert, nur das Speichern ging schief. Der gespeicherte
      // refresh_token bleibt gueltig, der naechste Lauf versucht es erneut.
      spaeter.push(row.user_key + ' (Speichern: ' + String((e && e.message) || e).slice(0, 80) + ')');
    }
    continue;
  }
  const fehler = String(tok.error || '');
  const code = (JSON.stringify(tok).match(/AADSTS\d+/) || [fehler || ('HTTP ' + status)])[0];
  if ((status === 400 || status === 401) && PERSOENLICH.includes(fehler)) {
    await vermerken(row.user_key, 'reconnect_required', (code + ' ' + fehler).trim());
    kaputt.push(row.user_key + ' (' + code + ')');
  } else {
    const wer = (fehler === 'invalid_client' || fehler === 'unauthorized_client') ? 'App-Zugang, Betreiber' : 'voruebergehend';
    await vermerken(row.user_key, 'connected', 'Erneuerung gescheitert (' + wer + '): ' + code);
    spaeter.push(row.user_key + ' (' + wer + ', ' + code + ')');
  }
}

return [{ json: { result: 'Erneuert: ' + (ok.join(', ') || 'keine')
  + (kaputt.length ? ' | Muss neu verbinden: ' + kaputt.join(', ') : '')
  + (spaeter.length ? ' | Naechster Lauf versucht es erneut: ' + spaeter.join(', ') : '') } }];
